// === Tab: sketch.js ===
var program;
let screen;
let grid;
let cols, rows;
let resolution = 20;

function make2DArray(cols, rows) {
  let arr = new Array(cols);
  for (let i = 0; i < arr.length; i++) {
    arr[i] = new Array(rows);
  }
  return arr;
}

function preload() {
  program = loadShader("https://openprocessing.org/sketch/1928898/files/vert.glsl", "frag.glsl");
}

function mouseMoved() {
  let mPosX = floor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / resolution);
  let mPosY = floor((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / resolution);
  for (i = -1; i < 2; i++) {
    for (j = -1; j < 2; j++) {
      let col = (mPosX + i + cols) % cols;
      let row = (mPosY + j + rows) % rows;    
      grid[col][row] = 1;
    }
  }
}

function setup() {
  // pixelDensity(1);
  createCanvas(windowWidth,windowHeight, WEBGL);
  screen = createGraphics(width, height);
  cols = floor(width / resolution);
  rows = floor(height / resolution);

  screen.noStroke();

  grid = make2DArray(cols, rows);
  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      let lit = floor(random(15));
      if(lit == 1){
        grid[i][j] = 1;
      } else {
        grid[i][j] = 0;
      }

    }
  }
}

function draw() {
  shader(program);
  screen.background(0);

  program.setUniform("texture", screen);
  program.setUniform("u_time", millis() / 1000);
  program.setUniform("pNoise", getNoiseValue());


  mouseMoved();

  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      let x = i * resolution;
      let y = j * resolution;
      if (grid[i][j] == 1) {
        screen.fill(255);
        screen.rect(x, y, resolution - 0.5, resolution - 0.5);
      }
    }
  }

  let next = make2DArray(cols, rows);

  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      let state = grid[i][j];

      // count live neighbors;

      let neighbors = countNeighbors(grid, i, j);

      if (state == 0 && neighbors == 3) {
        next[i][j] = 1;
      } else if (state == 1 && (neighbors < 2 || neighbors > 3)) {
        next[i][j] = 0;
      } else {
        next[i][j] = state;
      }
    }
  }

  grid = next;

  rect(-width / 2, -height / 2, width, height);
}

function countNeighbors(grid, x, y) {
  let sum = 0;
  for (let i = -1; i < 2; i++) {
    for (let j = -1; j < 2; j++) {
      // use modulus to get infinite edges
      // 0->end & end->0
      var col = (x + i + cols) % cols;
      var row = (y + j + rows) % rows;

      sum += grid[col][row];
    }
  }
  sum -= grid[x][y];

  return sum;
}

function getNoiseValue() {
  let v = noise(millis() / 100);
  const cutOFF = 0.5;

  if (v < cutOFF) {
    return 0;
  }

  v = pow(((v - cutOFF) * 1) / (1 - cutOFF), 2);

  return v;
}


