// === Tab: frag.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

varying vec2 vTexCoord;

// uniform vec2 u_resolution;
// uniform vec2 u_mouse;
uniform float u_time;

uniform sampler2D texture;
uniform float pNoise; 

#define PI 3.14159265359


vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

float snoise(vec2 v) {
    const vec4 C = vec4(0.211324865405187,  // (3.0-sqrt(3.0))/6.0
                        0.366025403784439,  // 0.5*(sqrt(3.0)-1.0)
                        -0.577350269189626,  // -1.0 + 2.0 * C.x
                        0.024390243902439); // 1.0 / 41.0
    vec2 i  = floor(v + dot(v, C.yy) );
    vec2 x0 = v -   i + dot(i, C.xx);
    vec2 i1;
    i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod289(i); // Avoid truncation effects in permutation
    vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
        + i.x + vec3(0.0, i1.x, 1.0 ));

    vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
    m = m*m ;
    m = m*m ;
    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
    vec3 g;
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return 130.0 * dot(m, g);
}

#define NUM_OCTAVES 5

float fbm ( in vec2 _st) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    // Rotate to reduce axial bias
    mat2 rot = mat2(cos(0.5), sin(0.5),
                    -sin(0.5), cos(0.50));
    for (int i = 0; i < NUM_OCTAVES; ++i) {
        v += a * snoise(_st);
        _st = rot * _st * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}

float fbmTexture(in vec2 st) {
    vec2 q = vec2(.0);
    q.x = fbm(st*.1 + .0*u_time + vec2(533., 123.));
    q.y = fbm(st*.1 + .1*u_time + vec2(12., 55.));

    // add vec2 offset & animate
    vec2 r = vec2(.0);
    r.x = fbm(st*.1 + q*.5 + .0*u_time + vec2(896., 123.));
    r.y = fbm(st*.1 + q*.5 + .1*u_time + vec2(89., 17.));

    float f = fbm(st+r.x*4.);

    return f;
}

void main() {
    vec2 st = vTexCoord;
    st.y = 1.-st.y;

    vec2 offset = vec2(.0, .02);

    float f = fbmTexture(st);

    vec3 col = vec3(.0);

    vec2 uvOffset = vec2(.0);

    uvOffset.y = tan(snoise(st*463.+u_time*.05)*PI/2.)*.01
                + snoise(st*6. + u_time*.5)*.01;

    col.r = texture2D(texture, st + uvOffset + offset).r;
    col.g = texture2D(texture, st + uvOffset).g;
    col.b = texture2D(texture, st + uvOffset - offset).b;

    vec3 col2 = vec3(f)+.2;

    gl_FragColor = vec4(col, 1.0);
}

